INSERT INTO damage_scenario (id, item_definition_id, title) VALUES
    ('b6690fbf-aed9-5c4f-8789-411f45b10906', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The cells are put into a dangerous state because the CMC incorrectly monitors and controls the battery cells.'),
    ('97194547-f1c9-51c4-9722-de65dbc07538', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The available battery capacity is reduced because incoming balancing request from the BMS are not executed properly.'),
    ('0d84b61f-7008-5e49-948f-90ffb58096dd', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The vehicle cannot be driven properly because the states of the battery cells are not available.'),
    ('29c702f2-aecf-594a-ba9e-be3b11464b81', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The vehicle/battery OEM loses business advantages because the CMC firmware is publicly disclosed.'),
    ('6459be02-724e-5cd5-a679-d02749261620', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The battery states are calculated wrongly because the cell/module data is altered during transfer.'),
    ('8e711c0b-ead8-5de8-834d-a15d5d75552b', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The battery is monitored falsly caused by incorrect cell/module data altered during transfer.'),
    ('6727e212-d3a0-5422-a38f-46f34086ae19', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The battery states cannot be calculated because the transfer of cell/module data is interrupted.'),
    ('89bf06a9-89e9-5077-9f35-f3f19669f28d', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The battery cannot be monitored caused by missing cell data because the transfer ot cell data is interrupted.'),
    ('d1642cf6-b627-5231-b290-ec8ca2b98115', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'BMS becomes blind to the thermal state of the battery. No thermal protection without data. Thermal Runaway.'),
    ('e0a2be00-3387-52b8-94aa-d336f96dd560', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Undetected Degradation. Cell aging accelerates silently'),
    ('c011d5e3-6276-56e9-a5b5-7a462c35610b', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Battery power limitation. BMS will reduce power output of battery in case the temperature is to high.'),
    ('03ca0ace-fd74-557d-9648-8a01f6b07c65', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The battery cells are put into a dangerous state resulting from CMC firmware that was manipulated during update process.'),
    ('4a52ee49-dc33-5823-a9ad-b3878cfa5ef9', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The CMC does not function properly due to rollback to an old, obsolete firmware version.'),
    ('1a2956b5-e531-5af8-90a0-7c4604fa0cec', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The CMC does not function properly due to the prevention of firmware updates, thus fixing bugs and vulnerabilities.'),
    ('d520fd70-7ba1-5c84-b47a-fc87b62eaa4a', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The vehicle cannot be driven anymore because the installation of a critical firmware update is prevented.'),
    ('f7cb9217-59a7-5c50-8398-6f2c5cb236d3', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Battery cell is overcharged or overdischarged, caused by falsified balancing command.'),
    ('85645a42-0d71-52e2-b3b5-02619f29b9ef', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Battery cell is overcharged or overdischarged, caused by missing balancing command.'),
    ('c8445363-70e0-5cb4-8706-21ea5732a0f4', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Incorrect state estimation, loss of current, voltage, temperature protection'),
    ('ba5b1059-d79b-5131-b5f6-02162c14a249', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Messages blocked. Fail to calculate models, fail to update battery passport'),
    ('454a06ed-a7a8-5943-97c9-c02b8b6ac2d9', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The vehicle/battery OEM loses business advantages because the BMS firmware is publicly disclosed.'),
    ('cb92eb44-6a00-519a-b426-88d9a0b6ff1d', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The battery is put into a dangerous state because the BMS incorrectly monitors and controls the battery pack.'),
    ('9c1bbdfb-15e8-52e3-b503-35b5b8c4ac98', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The available battery capacity is reduced by incorrect balancing requests from the BMS.'),
    ('4d288a22-c738-5741-93f9-3e7f9bc0f1da', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The resell value of the battery is manipulated because the SoH is incorrectly calculated by the BMS.'),
    ('fa070d08-18b8-5510-b490-0fb8a503699d', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The vehicle cannot be driven because the states of the battery are not available.'),
    ('f8cfadfc-7a14-505c-a6fa-b7fd8c89fac6', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Resale value of battery is decreased because false extreme conditions in battery passport are reported.'),
    ('1c7ab801-75b1-5bad-a373-1244a4fcb4c8', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The capacity of the battery is reduced, caused by falsified balancing information.'),
    ('5739d862-1717-551c-8668-18169bac3521', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The capacity of the battery is reduced, caused by missing balancing information.'),
    ('fe6ee4bc-e78b-57fa-a7d4-7cafd777bc05', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The lifespan of the battery and the vehicle is reduced because of unbalanced battery cells.'),
    ('0e6e7722-d02f-52a5-b64c-f9f4018605dd', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The battery is put into a dangerous state resulting from BMS firmware that was manipulated during update process.'),
    ('ca736798-facd-5836-a37a-bff0fb19fea6', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The BMS does not function properly due to rollback to an old, obsolete firmware version.'),
    ('1985f31c-a94b-558f-b7c3-aaba80425f43', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The BMS does not function properly due to the prevention of firmware updates, thus fixing bugs and vulnerabilities.'),
    ('3f95ef11-54cc-5927-9d59-c8dc055aa8b4', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The SoC and SoH of the vehicle are known to external parties because the battery data is publicly disclosed.'),
    ('22f8dad4-8b78-583e-8db0-2b3ec101b1e9', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The reselling value is increased/decreased because the SoH are displayed falsely caused by altered battery data during transfer.'),
    ('794ff82a-c5b6-599e-a7cf-67f9ac9a3d59', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The operational availability of the vehicle is reduced because the SoC is not displayed in the IVI due to an interrupted transfer of data.'),
    ('1da6fc4e-d453-52f3-815a-ee176af86b41', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The vehicle''s performance is reduced because of altered battery states.'),
    ('4c4ca356-0fed-52ae-af17-8a576c05c0bd', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The vehicle cannot be driven anymore because the transfer of battery states to the VCU is disabled.'),
    ('d9be513a-f082-5a64-b725-bac4d36c52e1', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'If the battery fingerprint (a unique identifier of the cells'' performance characteristics) fails or becomes corrupted, the BMS may misidentify the battery and apply inaccurate control parameters. In case the BMS doesn''t recognize the identifier it can interrupt battery opration and display an error.'),
    ('4b81cc8c-fb6e-5380-8f23-946a039b7699', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'False charge/discharge mode. False commands lead to over/undercharging'),
    ('e79952b8-c18c-5ec1-a379-17f69a978b02', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The vehicle''s performance is reduced because of altered VCU demands.'),
    ('0a269de7-9859-5da2-9a10-8d5e1b9a1746', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The vehicle cannot driven anymore because the transfer of VCU demands is disabled.'),
    ('2a491a34-59ab-5954-821b-33cb2ede8f81', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Battery cell overcharge, overdischarge, overtemperature protections are not functioniong, because CMC receives false data.'),
    ('455bfc50-5cf1-52f0-bf3d-d72e7df504c2', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'SoX calculation, firmware updates, the Battery Passport data transmitted from cloud to gateway becomes available to third parties.'),
    ('faf28d60-3c34-5afd-86e0-839a46a579f7', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Messages tampered. Malicious firmware update, fake models pushed'),
    ('2381bf7e-3877-596b-b873-7d5795e0b9a4', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Messages blocked. Fail to receive models calculations, potentially degrading performance.'),
    ('efa62de4-1f8a-5d08-92ca-0b422a48e961', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'SoX calculation becomes available to third parties potentially being sold to competitors or used to infer operational behaviors.'),
    ('1e888c07-69d0-5641-b202-9aec6264bb3c', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'SoX calculations manipulated. Resale value of the vehicle is influenced.'),
    ('a9966168-26a7-52cb-9e65-9092228d1a79', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'SoX calculations are not available and the functionality of battery is reduced. Only SoX calculations at BMS is available.'),
    ('080c52fd-3b1f-5d95-88ee-66e8d406bd05', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The OEM loses business advantage because firmware images are publicly disclosed.'),
    ('efccbbd2-1481-52d1-a6c9-b60c3e398bd4', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Unfixed vulnerabilities are exploited because firmware configuration data (version, etc.) of BMS components (gateway, BMS, CMC) are disclosed.'),
    ('25bc2572-ae75-53b1-bdfd-4391e53a8b89', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The BMS components (BMS/CMC) are put into a dangerous state because firmware images are manipulated.'),
    ('89d39999-cf14-5a65-88a2-09353a90832d', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The BMS components (BMS/CMC) do not operate properly because firmware images are manipulated.'),
    ('c0f4303e-e9d7-580c-ac0b-1570d15d58a5', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The BMS components (BMS/CMC) receive outdated firmware updates because the firmware updates service is manipulated.'),
    ('efa09e93-8ccf-586c-bb0d-eb6c6844ae38', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'No firmware updates are installed, because the firmware update service is disrupted.'),
    ('eb9077a4-7c47-56ae-809d-a4f7f6cc17e8', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Confidential battery passport data becomes available to third parties, exposing confidential information such as battery origin, usage history, or ownership, allowing third parties to infer sensitive operational or commercial details.'),
    ('5afedbc5-a1b8-5069-8980-4319714d901e', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Battery passport data is manipulated. Resale value of the vehicle is influenced. State of battery is falsely represented as deteriorated and warranty is not covered.'),
    ('734bc155-d97e-57f0-b476-3816df027c98', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Battery passport data is deleted, preventing access to critical lifecycle and traceability information, disrupting resale, compliance, or warranty verification processes.'),
    ('b12c530e-c2e5-54ee-9ab2-018a8e2250cb', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The vehicle/battery OEM loses business advantages because the gateway firmware is publicly disclosed.'),
    ('e3423022-bc1c-5a09-ae06-03732cef7847', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Tampering with models. Not authorized access'),
    ('bf33e727-cd26-5dc9-8231-42e0d72d8699', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'No data upload to cloud (Battery Passport, data models)'),
    ('fcea4ab5-59eb-5b40-894b-8bda4b4b3a59', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'No data transfer to BMS (SoX calculation, firmware updates)'),
    ('d9a54370-1c0b-5bc9-86d3-d1966bceda8d', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'SoX calculation, the Battery Passport data transmitted from gateway to cloud becomes available to third parties.'),
    ('c1c933a7-c1e4-5a43-a2f9-a8c96ebb32ae', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The cloud-based data storage does not reflect the actual state of the battery, because data is manipulated during transfer to the cloud, which may lead to wrong decisions regarding maintenance, warranty, or resale.'),
    ('44b033f0-ad6a-587b-ab0c-4bbc16145a23', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'There is no connection to cloud services, because the communication between gateway and cloud is disrupted, causing loss of real-time monitoring and updates critical for battery management.'),
    ('ffa3072c-d864-5052-9b07-324cefe44bf0', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The gateway does not function properly due to rollback to an old, obsolete firmware version.'),
    ('e898add5-7f0e-54dc-9f95-eae7a3c9809e', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The gateway does not function properly due to the prevention of firmware updates, thus fixing bugs and vulnerabilities.'),
    ('99092733-679d-59bf-9987-50f77fe55099', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The gateway does not operate anymore because the installation of a critical firmware update is prevented.'),
    ('847c620e-6c10-546e-ae7c-cbacd523c880', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'SoX calculation, firmware updates, the Battery Passport data transmitted from gateway to BMS becomes available to third parties.'),
    ('e632c758-65b0-53ef-8470-eb9bc346f128', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The data transmitted from gateway to BMS becomes corrupted. SOC calculation is wrong and battery is put in a dangerous state.'),
    ('f5a97ec1-1532-5dfc-8163-51f1b22725cd', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'There is no transfer of data (firmware/configuration updates) to the BMS, leading to outdated or missing critical updates in the BMS.'),
    ('e57df8bd-c930-506e-956e-c696a4ef1011', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The vehicle is put into a dangerous state because the functionality of overcharge protection is altered.'),
    ('7d87c27e-6c52-5254-9ef8-5a3bb8ca0b18', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Lithium plating/internal short circuits. Electrolyte decomposition. Transition metal dissolution. SEI decomposition. Battery rupture.'),
    ('1d14dc54-97ce-5d04-8bbb-e8705434ddf4', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The vehicle is placed in a dangerous condition because the overcharge protection system is disabled.'),
    ('eace3190-7084-5e89-b6cc-88735cc3a630', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The vehicle is put into a dangerous state because the functionality of overdischarge protection is altered. SEI decomposition and formation of copper dendrites as well as generate CO, CO2, H2 and O2. Reformed SEI is unstable after recharge. Internal short circuit'),
    ('2e9ac780-aba7-569b-bfac-00c8dacf1e97', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The vehicle is placed in a dangerous condition because the overdischarge protection system is disabled.'),
    ('3362426b-8044-54d8-8b64-c83e3a45df43', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The vehicle cannot be operated anymore because the battery is deeply discharged, because the overdischarge protection system is disabled.'),
    ('0de4cce3-b45f-501e-9e89-789ea6f1c194', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The vehicle is put into a dangerous state because the functionality of overtemperature protection is altered. High temperatures can trigger thermal runaway. SEI decomposition, Anode and electrolyte react. Polymer separator melting. Cathode decomposition. Electrolyte decomposition. Short circuit. Electrolyte burning. Thermal runaway'),
    ('68e23ffa-8b36-5e72-964e-a060c8fa3b2e', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The vehicle is placed in a dangerous condition because the overtemperature protection system is disabled.'),
    ('c8858cc6-a4a0-56f3-bcce-41638b9ff142', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The vehicle is put into a dangerous state because the functionality of under-temperature protection is altered. Charging may continue at low temps, causing lithium plating on the anode, which can lead to dendrite formation and internal short circuits.'),
    ('20c02143-dc80-5243-b53e-93943b93ce82', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'The vehicle is placed in a dangerous condition because the under-temperature protection system is disabled.'),
    ('e952b40e-81d5-50f4-b0f7-46a3d94f84d2', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'If SoH fails because the system calculates and receives incorrect SoH information, then BMS may: enter restricted operation, flag diagnostic trouble codes, alert of request service'),
    ('80a65c9c-c9e4-5ea3-af41-9b5952281c8f', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'If SoH fails because the system either can''t access SoH information, then BMS may: enter restricted operation, flag diagnostic trouble codes, alert of request service'),
    ('206c6616-47cb-5de8-9e06-9145e25a8510', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Over-Discharge and cell degradation. Cells get discharged below safe voltage limits. Cell reversal (very damaging)'),
    ('f9a78fc4-6fca-5010-a889-d50ab1d372a1', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Lithium plating, electrolyte breakdown, gas generation, swelling, heat generation. Thermal runaway'),
    ('4da8398b-c0c4-534d-b86f-3474b6cbf2ce', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'If the battery fingerprint (a unique identifier of the cells'' performance characteristics) fails or becomes corrupted, the BMS may misidentify the battery and apply inaccurate control parameters.'),
    ('68643b90-cfc1-5824-a5d8-2e6d256665fd', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'BMS misses early signs of degradation and predicts incorrectly maintenance intervals'),
    ('4c1b37b9-7b8b-58e3-9fb0-657cfa7a9808', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'EMS manufacturer loses business advantages because the EMS firmware is publicly disclosed.'),
    ('1a02b0c3-6d93-50f7-b8e9-71b1876c8655', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'Malicious code running into EMS firmware, leading to altered or unsafe system behavior.'),
    ('305f0dc3-4ea6-5e24-a1b7-f6060357615a', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'Charging/discharging is disabled because EMS is not functioning.'),
    ('d6382b62-7ffd-5fec-862d-be51fdd4decf', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'Messages disclosed allowing sabotage planning. Loss of customer trust due to data confidentiality violations.'),
    ('f80da4a5-38dd-5e12-8586-0e508c1462df', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'Messages tampered. PV and grid information falsified. Compromised energy dispatch planning, impacting grid stability or revenue.'),
    ('9c93c1a5-934e-59b1-ad7a-58b30915ea37', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'Messages blocked. PV and grid information not available. Loss of control over battery operations (charging/discharging), disrupting energy delivery. Potential triggering of emergency shutdown mechanisms'),
    ('a1e0bb6f-9e0e-5688-a41f-f8045147c267', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'Messages tampered. SoX data manipulated. Compromised energy dispatch planning, impacting revenue (e.g. lower SOC reported to decrease available capacity).'),
    ('690a1c1f-17e7-59c8-af58-a20f48cfb371', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'Messages blocked. SoX data not available. Loss of control over battery operations (charging/discharging), disrupting energy delivery. Potential triggering of emergency shutdown mechanisms'),
    ('589a6eb8-7fb5-5d08-a245-8eed409519c0', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'Messages tampered. Firmware image modified in transit, leading to installation failure or corrupted firmware running on EMS, causing altered or unsafe system behavior.'),
    ('db18cd5d-83b1-5862-b270-11e84dcd75c5', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'Firmware update blocked. EMS remains on outdated firmware, causing inability to deploy security patches or performance improvements.'),
    ('0e4a9a14-8959-5b67-9786-96f2862ecef2', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'Messages disclosed. PV and grid information obtained by third parties.'),
    ('59d2f60e-1de2-5a8c-bb51-17bceccb501b', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'Messages tampered. PV and grid information falsified.'),
    ('06872c47-57ea-5de6-ac71-fed030dfde89', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'Messages blocked. PV and grid information not available.'),
    ('043676b6-27d7-53f7-9d3a-8c1580562298', 'bc04d38b-440d-54c6-847d-4bd7ca873b28', 'Degradation of battery modules due to incorrect configuration for second-life conditions due to retained access privileges by the first-life operator to the firmware update interface.'),
    ('aeb32e0c-f60f-5bdb-9a10-57e5332405f2', 'bc04d38b-440d-54c6-847d-4bd7ca873b28', 'Firmware bricking may render the BMS or gateway non-functional'),
    ('7d6ee9d7-3ae6-5cae-a6eb-41465ea12d43', 'bc04d38b-440d-54c6-847d-4bd7ca873b28', 'Cryptographic keys, certificates, or communication tokens are not renewed. Confidential second-life data (e.g., energy use, grid participation patterns) is leaked.'),
    ('9f8837e5-ef35-5b7e-82a5-63660c4ac0d2', 'bc04d38b-440d-54c6-847d-4bd7ca873b28', 'Integrity of battery passport or SoX data is compromised due to conflicting inputs from multiple lifecycle actors.'),
    ('7f2a9157-0d00-598d-8407-809ced793027', 'bc04d38b-440d-54c6-847d-4bd7ca873b28', 'Cryptographic keys, certificates, or communication tokens are not renewed. Second-life operator loses control'),
    ('5b88d680-3871-51ba-8204-9d7836639ce3', 'bc04d38b-440d-54c6-847d-4bd7ca873b28', 'Loss or falsifications of battery passport records due to unauthorized access to the battery passport platform using old credentials.'),
    ('614dc533-a59f-58ab-b0a5-ed8bdb56eaad', 'bc04d38b-440d-54c6-847d-4bd7ca873b28', 'Theft of proprietary OEM strategies (e.g., energy management, safety control logic) because IP-protected data is not being deleted before transfer to the second life.'),
    ('81835178-d325-55c1-b1f6-b01c2a0ef920', 'bc04d38b-440d-54c6-847d-4bd7ca873b28', 'Inability to start due to wrong fingerprint because the fingerprint is manipulated during the transition.'),
    ('6e174a62-6b9f-5901-b526-f108a9f7461b', 'bc04d38b-440d-54c6-847d-4bd7ca873b28', 'Inability to start because the second-life operator does not have access to the storage of the fingerprint.'),
    ('79847f50-d890-5efe-8f8b-ce7901d98137', 'bc04d38b-440d-54c6-847d-4bd7ca873b28', 'The battery cells are put into a dangerous state resulting from CMC firmware that was manipulated during update process.'),
    ('8776c378-8791-557a-b6e1-67bdd34d086b', 'bc04d38b-440d-54c6-847d-4bd7ca873b28', 'The battery system cannot be used because the installation of a critical firmware update is prevented.'),
    ('371e51dc-1b67-5d4e-a428-bad9e658318f', 'bc04d38b-440d-54c6-847d-4bd7ca873b28', 'The battery cells are put into a dangerous state resulting from BMS firmware that was manipulated during update process.')
