INSERT INTO threat_scenario (id, item_definition_id, title, elicitation_method, cause_of_compromise, aggregated_attack_feasibility, max_risk_score) VALUES
    ('03af77d9-c5ec-58e2-8cc2-df1ce558d209', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Tampering with the installed CMC firmware leads to the loss of integrity of the CMC monitoring and control functions, causing the battery to enter a dangerous state.', 'STRIDE', 'Tampering', 'HIGH', 4),
    ('286eb9a5-78e9-5dfd-a37a-23e1642f4a28', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Tampering with the CMC firmware leads to the loss of integrity of the balancing functionalities, causing the battery to enter an unbalanced state thus reducing the available capacity.', 'STRIDE', 'Tampering', 'HIGH', 3),
    ('5d4a2cc9-1fb7-53f7-8aee-f7fd68bc32c4', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Denial-of-service of the CMC firmware leads to the loss of the cell data.', 'STRIDE', 'Denial of Service', 'MEDIUM', 3),
    ('3aaf9e94-280a-5b34-ae5b-32c8e506c667', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Information disclosure of the installed CMC firmware leads to intellectual property theft, enabling competitors or malicious actors to replicate or exploit proprietary functionality.', 'STRIDE', 'Information Disclosure', 'HIGH', 1),
    ('f3b00b53-7d10-507a-984b-bad6b4199814', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Tampering with communication between CMC and BMS via physical access to the diagnostic port leads to altering cell/module data.', 'STRIDE', 'Tampering', 'VERY_LOW', 1),
    ('3d955f99-8a84-51a9-bcc4-6cccb5d91041', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Tampering with communication between CMC and BMS via remote access (Wi-Fi/4G/IVI) leads to altering cell/module data.', 'STRIDE', 'Tampering', 'LOW', 2),
    ('936fb2d7-4674-5916-b1b0-846f1fa0972e', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Denial-of-service by flooding the bus causes communication failure between CMC and BMS, preventing calculation of battery states.', 'STRIDE', 'Denial of Service', 'VERY_LOW', 1),
    ('b72e2a0d-663e-5ab0-bddb-e8e8347686f0', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Denial-of-service by a manipulated ECU causes communication failure between CMC and BMS, preventing calculation of battery states.', 'STRIDE', 'Denial of Service', 'MEDIUM', 4),
    ('68b34437-2635-50d0-9fd4-3a1c9dcd6f0c', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Tampering with temperature data prevents BMS from detecting overheating resulting a thermal runaway.', 'STRIDE', 'Tampering', 'MEDIUM', 4),
    ('75686c5b-a71f-5c53-bbda-5482dc4f1554', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Tampering with temperature data causes BMS to underestimate thermal stress and results in decreased battery health.', 'STRIDE', 'Tampering', 'MEDIUM', 2),
    ('fc3e6295-1d3d-57ea-9da5-5af8d91cb313', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Tampering with temperature data when false high-temperature or low-temperature data is communicated causes BMS to limit battery power.', 'STRIDE', 'Tampering', 'MEDIUM', 2),
    ('88336b08-ac98-52e7-8d4a-ce699a1483e0', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Information disclosure of the CMC firmware during update leads to intellectual property theft, enabling competitors or malicious actors to replicate or exploit proprietary functionality.', 'STRIDE', 'Information Disclosure', 'VERY_LOW', 1),
    ('74b8a65f-0944-5007-9141-c9ecf9bc465f', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Tampering with the CMC firmware during update leads to the loss of integrity of the CMC monitoring and control functions, causing the battery to enter a dangerous state.', 'STRIDE', 'Tampering', 'HIGH', 5),
    ('9d59b88a-f2d6-5f99-91bb-c19bfe7934d9', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Repudiation of CMC firmware rollback leads to reinstalling outdated firmware with known bugs or security flaws, degrading system performance.', 'STRIDE', 'Repudiation', 'LOW', 2),
    ('babd27d6-b809-539e-8bb6-158e05399347', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Denial of Service of CMC firmware updates leaves software bugs and vulnerabilities unpatched, resulting in degraded functionality or exposure to known exploits.', 'STRIDE', 'Denial of Service', 'MEDIUM', 3),
    ('79019d09-6e01-5d99-a8e8-cbe0fd061e7c', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Denial of Service of CMC firmware update leaves the CMC non-functional, preventing the vehicle from starting.', 'STRIDE', 'Denial of Service', 'MEDIUM', 4),
    ('ad01ca16-4c64-5e1d-a10d-9ae98998901a', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Tampering with communication from BMS to CMC leads to false balancing commands, causing it to incorrecty charge or discharge cells.', 'STRIDE', 'Tampering', 'VERY_LOW', 1),
    ('1b1dd228-8d33-5af3-9bc2-dc79640ef245', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Denial of Service of communication from BMS to CMC leads to missing balancing commands, causing it to incorrecty charge or discharge cells.', 'STRIDE', 'Denial of Service', 'VERY_LOW', 1),
    ('9a63fbd6-0851-5fcb-802f-5538da2093d9', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Tampering with data communicatoin from the CMC to the BMS, leads to BMS receiving false data from the CMC.', 'STRIDE', 'Tampering', 'MEDIUM', 3),
    ('eddd953e-04ed-5435-8480-585e41e9abf3', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Denial-of-service of data communication between the CMC and BMS prevents the BMS from receiving CMC data.', 'STRIDE', 'Denial of Service', 'HIGH', 3),
    ('d0ff7d7b-ccf8-53f3-a510-f6accff095d8', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Information disclosure of the installed BMS firmware leads to intellectual property theft, enabling competitors or malicious actors to replicate or exploit proprietary functionality.', 'STRIDE', 'Information Disclosure', 'HIGH', 1),
    ('3583d118-27ef-56bd-ac37-a520b8ad5e85', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Tampering with the installed BMS firmware leads to the loss of integrity in monitoring and control functions, causing the battery pack to operate outside safe parameters.', 'STRIDE', 'Tampering', 'HIGH', 4),
    ('ab8f18c4-115c-53f9-9420-1b22cd45b044', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Tampering with the BMS firmware causes it to generate incorrect balancing requests, leading to suboptimal cell usage.', 'STRIDE', 'Tampering', 'VERY_LOW', 1),
    ('6422a960-7f60-5c41-acb5-35b55af0325e', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Tampering with the BMS firmware affects the calculation of the battery’s SoH, leading to falsified SoH reports', 'STRIDE', 'Tampering', 'VERY_LOW', 1),
    ('f2ba4b9a-fde2-50a2-82ae-877547c2eee7', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Denial-of-service of BMS prevents reporting battery states.', 'STRIDE', 'Denial of Service', 'MEDIUM', 4),
    ('1419eaaf-95d7-5888-b3d2-8834286d8ee6', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Tampering with communication between BMS and battery passport leads to false data in battery passport causing its resale value to decrease', 'STRIDE', 'Tampering', 'MEDIUM', 2),
    ('abca9655-80f7-52e7-a964-5da83e5f13c0', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Tampering with communication between BMS and CMC leads to false balancing information thus reducing the battery''s capacity.', 'STRIDE', 'Tampering', 'MEDIUM', 2),
    ('4414dba8-2557-5dbc-a452-dc320e258a13', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Denial-of-service of communication between BMS and CMC leads to missing balancing information thus reducing the battery''s capacity.', 'STRIDE', 'Denial of Service', 'MEDIUM', 2),
    ('b619da38-7067-595f-b138-9d39c101811f', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Tampering with communication between BMS and CMC leads to unbalanced cells thus reducing the lifespan of the battery and the vehicle.', 'STRIDE', 'Tampering', 'MEDIUM', 2),
    ('1466a250-5c10-597c-ad05-908746d31ce5', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Information disclosure of the BMS firmware during update leads to intellectual property theft, enabling competitors or malicious actors to replicate or exploit proprietary functionality.', 'STRIDE', 'Information Disclosure', 'VERY_LOW', 1),
    ('0c94ef53-28c3-521b-8391-b4e9d5a1cd41', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Tampering with the BMS firmware during update leads to the loss of integrity in monitoring and control functions, causing the battery pack to operate outside safe parameters.', 'STRIDE', 'Tampering', 'HIGH', 5),
    ('de237e5b-abc6-5ce1-bb07-7af94d3c3f85', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Repudiation of BMS firmware rollback leads to reinstalling outdated firmware with known bugs or security flaws, degrading system performance.', 'STRIDE', 'Repudiation', 'LOW', 2),
    ('aeedf901-9992-543d-ad5a-847157bf4420', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Denial of Service of BMS firmware updates leaves software bugs and vulnerabilities unpatched, resulting in degraded functionality or exposure to known exploits.', 'STRIDE', 'Denial of Service', 'MEDIUM', 3),
    ('99b54978-8905-511d-8be9-3669e7a170a9', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Denial of Service of BMS firmware update leaves the BMS non-functional, preventing the vehicle from starting.', 'STRIDE', 'Denial of Service', 'MEDIUM', 4),
    ('cd898862-b9f2-5969-9394-68265d2fe3c4', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Information disclosure of SoC and SoH leads to public disclosure of information available only to the person with legitimate interest.', 'STRIDE', 'Information Disclosure', 'HIGH', 3),
