    ('a8487ddf-4bac-5c58-888d-4dbcf2ea51d7', 'd85ff0ef-a086-56b3-961a-e78b6054798b', '8776c378-8791-557a-b6e1-67bdd34d086b')
INSERT INTO attack_path (id, item_definition_id, title, attack_steps_and_weaknesses) VALUES
    ('0a71fd31-4f26-5c2b-a158-f572b7d479b1', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains access to the cloud backend or over-the-air (OTA) update infrastructure.', '{"steps":["Attacker gains access to the cloud backend or over-the-air (OTA) update infrastructure.","Firmware update goes from cloud → telematics control unit → BMS → CMC","Malicious firmware is executed by the CMC.","Battery system enters unsafe state."]}'),
    ('6cdf388a-e743-56bd-a96a-ade6c104e7fc', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains access to the CMC firmware update process.', '{"steps":["Attacker gains access to the CMC firmware update process.","Malicious firmware is installed to disrupt balancing logic.","The tampered firmware disables or ignores balancing commands from the BMS.","Cells remain unbalanced over charge/discharge cycles.","Battery capacity is reduced due to early voltage cutoffs or safety limits triggered by unbalanced cells."]}'),
    ('feb73282-4a88-5124-9e60-d75336c3108a', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker initiates a denial-of-service attack targeting the CMC firmware.', '{"steps":["Attacker initiates a denial-of-service attack targeting the CMC firmware.","CMC becomes unresponsive or crashes, stopping cell data acquisition.","No cell voltage, temperature, or state data is sent to the BMS.","BMS cannot assess battery safety status. Vehicle enters restricted or non-operational mode, preventing normal driving."]}'),
    ('49cefeda-a826-5d05-9022-cc1e10471d30', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains unauthorized access to internal systems or update channels.', '{"steps":["Attacker gains unauthorized access to internal systems or update channels.","CMC firmware is extracted through debugging interfaces.","Firmware is reverse-engineered to reveal proprietary algorithms or control logic.","Competitors replicate the functionality or identify vulnerabilities."]}'),
    ('1450f8ee-553e-5c1a-bb16-bb3d2433740a', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains access to in-vehicle CAN or LIN bus via physical access to diagnostic port (OBD-II).', '{"steps":["Attacker gains access to in-vehicle CAN or LIN bus via physical access to diagnostic port (OBD-II).","Sniffs messages between CMC and BMS over the internal bus.","Injects forged packets with modified voltage/current data.","BMS accepts falsified data as legitimate."]}'),
    ('c5f37c5f-4e30-535d-95c0-663d3870d8d9', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker compromises vehicle network stack via Wi-Fi/4G update service or IVI vulnerability.', '{"steps":["Attacker compromises vehicle network stack via Wi-Fi/4G update service or IVI vulnerability.","Gains access to internal bus and tampers CMC data packets.","Alters temperature or voltage values to safe-looking but false readings.","BMS misinterprets the battery’s health and status."]}'),
    ('47d69e05-b23f-538f-8bcb-d754a5e19828', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker connects a malicious device to OBD-II port or injects via a compromised ECU.', '{"steps":["Attacker connects a malicious device to OBD-II port or injects via a compromised ECU.","Floods the bus with high-priority messages, delaying or blocking CMC data.","BMS receives incomplete or no cell/module data and fails to calculate battery states"]}'),
    ('af7e9260-03d3-5abc-8e85-4ed9259f18db', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker uploads malicious firmware to an ECU via an insecure OTA update.', '{"steps":["Attacker uploads malicious firmware to an ECU via an insecure OTA update.","ECU continuously jams or drops CMC–BMS messages.","Cell data fails to reach BMS and monitoring functions in the BMS are disabled due to missing input."]}'),
    ('31f9163c-3172-5435-973b-9e062eb2e347', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains access to the communication channel between the CMC and BMS, physically or via network vulnerability.', '{"steps":["Attacker gains access to the communication channel between the CMC and BMS, physically or via network vulnerability.","The attacker intercepts temperature data packets sent by the CMC.","The attacker modifies the temperature readings to appear normal.","The BMS receives falsified temperature data, believing the battery is operating within safe limits. Overheating events go undetected; the BMS does not activate cooling or shutdown procedures."]}'),
    ('80187084-2b6e-5c42-99b3-ea5dc2e4f7bf', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker exploits weak or missing encryption/authentication in the wireless protocol used between CMC and BMS (e.g., proprietary RF, BLE, or Wi-Fi).', '{"steps":["Attacker exploits weak or missing encryption/authentication in the wireless protocol used between CMC and BMS (e.g., proprietary RF, BLE, or Wi-Fi).","Gains wireless access within physical range of the vehicle (e.g., parked EV).","Intercepts and modifies temperature data packets in transit.","Replaces real readings with falsely low values to hide thermal stress. BMS assumes cells are operating within safe temperature range."]}'),
    ('a3e2abe0-8f9b-5f9f-b05b-2a47b03ffd5e', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker exploits weak authentication in the wireless protocol between CMC and BMS.', '{"steps":["Attacker exploits weak authentication in the wireless protocol between CMC and BMS.","Gains nearby wireless access and injects falsified temperature data.","Sends false high-temperature or low-temperature readings to BMS.","BMS interprets temperatures as unsafe and triggers thermal protection logic."]}'),
    ('c9f36490-27db-54d8-9cf3-68a6f1be0b68', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker exploits insecure CMC firmware update channel (e.g., lack of encryption or authentication in OTA or diagnostic update process).', '{"steps":["Attacker exploits insecure CMC firmware update channel (e.g., lack of encryption or authentication in OTA or diagnostic update process).","Intercepts and extracts the firmware binary during update or from an exposed ECU.","Analyzes the firmware to reverse-engineer proprietary algorithms and configurations.","Leverages stolen IP for competitive advantage or to develop targeted attacks."]}'),
    ('f94ff3cb-5ea3-5ab2-9702-ba22a18954bf', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker exploits lack of secure boot or firmware authentication in the CMC update mechanism (e.g., via unsecured OTA or diagnostic interface).', '{"steps":["Attacker exploits lack of secure boot or firmware authentication in the CMC update mechanism (e.g., via unsecured OTA or diagnostic interface).","Uploads manipulated firmware to the CMC that disables or alters critical monitoring/control logic.","CMC fails to detect or respond correctly to overvoltage, undervoltage, or overtemperature conditions. BMS receives false data from CMC."]}'),
    ('dce5ec23-e7df-54a1-b683-227fa8f5705e', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker exploits lack of firmware version control or rollback protection in the CMC update process.', '{"steps":["Attacker exploits lack of firmware version control or rollback protection in the CMC update process.","Initiates rollback to an older, vulnerable firmware version via diagnostic port or insecure OTA interface.","CMC operates with outdated logic containing known bugs or disabled safety functions."]}'),
    ('11b4eaf6-2b84-54cd-be12-1104e4c2e356', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker blocks firmware update communication channel (e.g., via jamming, protocol spoofing, or misconfiguring OTA server or network settings).', '{"steps":["Attacker blocks firmware update communication channel (e.g., via jamming, protocol spoofing, or misconfiguring OTA server or network settings).","CMC fails to receive or apply critical firmware updates.","Known bugs or vulnerabilities in the outdated firmware remain unpatched.","CMC experiences degraded functionality or remains exposed to future attacks."]}'),
    ('226f6782-b828-5867-a542-6f4a45bcb98e', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker blocks the firmware update process (e.g., through wireless jamming, network spoofing, or corrupting the update package).', '{"steps":["Attacker blocks the firmware update process (e.g., through wireless jamming, network spoofing, or corrupting the update package).","CMC fails to install a critical firmware update.","Vehicle detects CMC as non-functional.","System checks prevent vehicle startup."]}'),
    ('2279d5e9-b3a8-5812-849c-976706dc0d27', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains access to in-vehicle wireless network used for BMS–CMC communication (e.g., via weak encryption/authentication).', '{"steps":["Attacker gains access to in-vehicle wireless network used for BMS–CMC communication (e.g., via weak encryption/authentication).","Intercepts and injects falsified balancing commands targeting the CMC.","Commands instruct CMC to overcharge or overdischarge specific cells. CMC executes unsafe balancing actions."]}'),
    ('3daf0598-280a-53d8-990a-1f951da8a2a9', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker disrupts wireless communication between BMS and CMC (e.g., via RF jamming or protocol-level interference).', '{"steps":["Attacker disrupts wireless communication between BMS and CMC (e.g., via RF jamming or protocol-level interference).","Balancing commands from BMS fail to reach the CMC.","CMC does not perform necessary cell balancing actions. Some cells become overcharged or overdischarged during operation."]}'),
    ('1d81790a-8a96-56a6-bcf4-c13b0c30d40f', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains proximity access to the vehicle’s wireless communication channel between CMC and BMS (e.g., Bluetooth, Wi-Fi, or proprietary RF).', '{"steps":["Attacker gains proximity access to the vehicle’s wireless communication channel between CMC and BMS (e.g., Bluetooth, Wi-Fi, or proprietary RF).","Exploits missing or weak encryption and authentication in the wireless protocol.","Performs a man-in-the-middle or replay attack to intercept and alter telemetry data packets (voltage, current, temperature) sent from CMC to BMS.","Injects manipulated, false data that misrepresents the battery’s actual state. BMS processes incorrect information."]}'),
    ('9075cf9d-ccea-5404-8656-6cdef54bf0cc', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains wireless access to CMC–BMS communication channel.', '{"steps":["Attacker gains wireless access to CMC–BMS communication channel.","Launches targeted jamming or floods the channel with noise or high-priority messages.","Blocks or delays CMC data packets from reaching BMS.","BMS cannot receive required data to calculate battery models or update the battery passport."]}'),
    ('08f9b048-24c1-5195-ab6d-0525629f475b', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains unauthorized access to the OTA update server or wireless update channel by exploiting weak authentication or exposed endpoints.', '{"steps":["Attacker gains unauthorized access to the OTA update server or wireless update channel by exploiting weak authentication or exposed endpoints.","Firmware image is downloaded or intercepted due to lack of end-to-end encryption or unsecured transmission.","Attacker reverse-engineers the firmware to extract proprietary control logic.","OEM intellectual property is replicated, counterfeited, or used for competitive advantage."]}'),
    ('ceac523e-18c9-51a9-9444-688d6eff78b4', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains access to the BMS via unsecured diagnostic port or OTA update channel.', '{"steps":["Attacker gains access to the BMS via unsecured diagnostic port or OTA update channel.","Uploads manipulated firmware lacking authentication or integrity checks.","Firmware alters BMS monitoring and control logic (e.g., voltage/temperature thresholds).","BMS sends incorrect control signals or fails to trigger protections."]}'),
    ('d81f274d-4b83-5fba-a871-f84cd033a43c', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker compromises BMS firmware through insecure update interface.', '{"steps":["Attacker compromises BMS firmware through insecure update interface.","Injects malicious firmware that generates incorrect cell balancing commands.","Cells become imbalanced due to unequal charging/discharging."]}'),
    ('36f4bf68-010b-5a39-9266-dde80725aa12', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker tampers with BMS firmware via unauthorized access to update mechanism.', '{"steps":["Attacker tampers with BMS firmware via unauthorized access to update mechanism.","Modifies SoH algorithm or falsifies reporting data.","BMS outputs manipulated SoH values to the system or cloud."]}'),
    ('52bbc704-1390-524a-b83d-ccd8772e22eb', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker initiates denial-of-service on the BMS (e.g., by crashing its firmware or blocking execution).', '{"steps":["Attacker initiates denial-of-service on the BMS (e.g., by crashing its firmware or blocking execution).","BMS becomes non-functional and fails to report battery status to the VCU or IVI.","Vehicle disables driving due to missing critical battery state data."]}'),
    ('a6d4a9a3-3349-5cea-97f2-e3febcf220e7', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains proximity to the wireless communication link between BMS and the battery passport backend (e.g., via Wi-Fi, BLE, or cellular).', '{"steps":["Attacker gains proximity to the wireless communication link between BMS and the battery passport backend (e.g., via Wi-Fi, BLE, or cellular).","Exploits weak or absent encryption/authentication in the wireless protocol.","Performs a man-in-the-middle (MitM) attack or injects spoofed messages.","Falsifies data such as high temperature exposure or overcharge events.","Battery passport logs false extreme conditions, reducing resale value."]}'),
    ('8d671627-9cc4-5950-a938-3545be34ad44', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains physical proximity to the vehicle to target the short-range wireless communication (e.g., BLE, Zigbee, proprietary RF) between BMS and CMC.', '{"steps":["Attacker gains physical proximity to the vehicle to target the short-range wireless communication (e.g., BLE, Zigbee, proprietary RF) between BMS and CMC.","Performs passive sniffing to analyze protocol and extract encryption keys or session info (due to weak/no encryption, static keys, or flawed key exchange).","Replays or injects manipulated balancing commands using forged messages with incorrect balancing values.","CMC receives and executes false balancing instructions, causing certain cells to be over- or under-utilized."]}'),
    ('edd7fc47-a3ec-57bf-b555-1fe05e7b23bb', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker jams the wireless frequency band used for BMS–CMC communication (e.g., using an SDR or jamming device).', '{"steps":["Attacker jams the wireless frequency band used for BMS–CMC communication (e.g., using an SDR or jamming device).","Balancing commands from the BMS fail to reach the CMC due to sustained interference.","CMC is unable to initiate balancing procedures."]}'),
    ('154b97eb-e644-5b69-9c25-2fba7fd90ff0', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker spoofs as the BMS after analyzing and reverse-engineering the wireless protocol.', '{"steps":["Attacker spoofs as the BMS after analyzing and reverse-engineering the wireless protocol.","Injects valid-looking but malicious commands (e.g., over-the-air messages without strong authentication).","CMC follows misleading balancing patterns, overusing certain cells and underusing others."]}'),
    ('5e4246f3-6593-5bf5-b1b7-71486cd47e3e', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains unauthorized access to the OTA update server or wireless update channel by exploiting weak authentication or exposed endpoints.', '{"steps":["Attacker gains unauthorized access to the OTA update server or wireless update channel by exploiting weak authentication or exposed endpoints.","Firmware image is downloaded or intercepted due to lack of end-to-end encryption or unsecured transmission.","Attacker reverse-engineers the firmware to extract proprietary control logic.","OEM intellectual property is replicated, counterfeited, or used for competitive advantage."]}'),
    ('afb8d1bb-0b73-5f80-88be-e3fedf5fe9d4', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker intercepts or accesses the firmware update process, either remotely (via OTA) or locally (via diagnostic interface).', '{"steps":["Attacker intercepts or accesses the firmware update process, either remotely (via OTA) or locally (via diagnostic interface).","Malicious firmware is injected by bypassing authentication or exploiting inadequate signature checks.","BMS installs tampered firmware lacking correct validation."]}'),
    ('d4ae58a6-d8a6-5a46-9be6-e562354f3394', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker captures a previously signed but outdated firmware version.', '{"steps":["Attacker captures a previously signed but outdated firmware version.","System lacks rollback protection mechanisms such as version counters or anti-replay tokens.","Old firmware is installed through a legitimate update channel or diagnostic interface.","Known vulnerabilities or logic bugs reappear, degrading system security or safety."]}'),
    ('27eab265-938d-50ce-9faf-5076e06a78bf', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker initiates a denial-of-service attack against the firmware update mechanism (e.g., jamming wireless update signal, spoofing DNS, or blocking IP traffic).', '{"steps":["Attacker initiates a denial-of-service attack against the firmware update mechanism (e.g., jamming wireless update signal, spoofing DNS, or blocking IP traffic).","Update is not delivered to the BMS.","BMS continues running outdated software with unpatched vulnerabilities, exposing it to further attacks or reduced performance."]}'),
    ('0ad45ae7-304d-5e8f-9e57-2325d308be38', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'During a critical update, attacker disrupts the OTA channel using a persistent denial-of-service or injection of corrupted firmware metadata.', '{"steps":["During a critical update, attacker disrupts the OTA channel using a persistent denial-of-service or injection of corrupted firmware metadata.","BMS fails to complete the update, resulting in an invalid or partially written firmware state.","The BMS halts battery management operations, triggering system interlocks."]}'),
    ('ad4a213b-3c84-501a-ad1b-ec81c9d810fc', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker exploits weak authentication on the BMS-to-IVI communication interface (e.g., Bluetooth, CAN over IP).', '{"steps":["Attacker exploits weak authentication on the BMS-to-IVI communication interface (e.g., Bluetooth, CAN over IP).","SoC and SoH data are intercepted in transit due to insufficient protection (e.g., lack of TLS or secure CAN protocols).","Data is extracted and transmitted to unauthorized third parties."]}'),
    ('799eb29d-e2e5-58bb-8b5e-6995c86582d4', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains access to the IVI or injects false CAN messages using a rogue device on the vehicle network.', '{"steps":["Attacker gains access to the IVI or injects false CAN messages using a rogue device on the vehicle network.","Battery data (SoC/SoH) is modified in transit between BMS and IVI due to lack of integrity checks or message authentication.","Falsified SoC/SoH values are displayed to the user."]}'),
    ('a28aa175-deeb-5a7e-b311-797761b508ed', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker performs a denial-of-service (DoS) attack on the BMS-to-IVI communication channel by jamming or flooding the CAN bus or wireless interface.', '{"steps":["Attacker performs a denial-of-service (DoS) attack on the BMS-to-IVI communication channel by jamming or flooding the CAN bus or wireless interface.","SoC information fails to reach the IVI due to message loss or timeout.","Driver is unable to assess current charge level, causing risk of unexpected shutdowns."]}'),
    ('e0487eb9-b69c-54d1-9989-dbc64a714063', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains access to the in-vehicle CAN bus via a compromised ECU or external diagnostic port.', '{"steps":["Attacker gains access to the in-vehicle CAN bus via a compromised ECU or external diagnostic port.","Tampered CAN frames or spoofed messages containing falsified battery data (e.g., false SoC, temperature, or voltage) are injected into the BMS → VCU communication path.","VCU misinterprets the battery state as unsafe and triggers conservative power management logic."]}'),
    ('3b1f2365-3402-53bb-86db-8c7c389953b5', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker initiates a denial-of-service attack by flooding or suppressing CAN messages on the BMS → VCU line (e.g., via replay attack, jamming, or blocking gateway).', '{"steps":["Attacker initiates a denial-of-service attack by flooding or suppressing CAN messages on the BMS → VCU line (e.g., via replay attack, jamming, or blocking gateway).","VCU fails to receive critical battery data such as SoC, temperature, or fault status within the expected timeframe.","VCU safety logic triggers a fail-safe mode due to lack of data."]}'),
    ('ed87a9a1-8263-59d1-b41d-cdcfd6b460f4', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains access to the wireless BMS communication interface via compromised firmware update mechanism.', '{"steps":["Attacker gains access to the wireless BMS communication interface via compromised firmware update mechanism.","The attacker modifies or replaces the stored battery fingerprint data used to identify cell chemistry, configuration, or performance history.","On system boot or runtime check, the BMS reads the falsified fingerprint and assumes an incorrect cell profile.","BMS applies unsuitable charge/discharge limits, thermal management, or balancing strategy."]}'),
    ('96ce14c9-9103-5c6d-970c-60e9fd2e8d18', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker exploits wireless communication between IVI and BMS via man-in-the-middle attack.', '{"steps":["Attacker exploits wireless communication between IVI and BMS via man-in-the-middle attack.","Charging demand messages from the IVI to the BMS are intercepted and altered in transit.","The BMS receives falsified commands indicating incorrect charge or discharge modes.","The BMS applies these invalid instructions to the battery system."]}'),
    ('0318a249-7fb4-5dd0-9d04-cb574cb1fa85', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains access to the in-vehicle network via wireless interface (e.g., Wi-Fi, Bluetooth, telematics unit, or compromised ECU).', '{"steps":["Attacker gains access to the in-vehicle network via wireless interface (e.g., Wi-Fi, Bluetooth, telematics unit, or compromised ECU).","VCU-to-BMS communication messages carrying energy demand are intercepted.","Altered messages are injected with false energy requests (e.g., lower power requirements).","The BMS interprets these falsified demands and reduces battery output unnecessarily."]}'),
    ('52ec9980-2f62-5f0b-bb37-b58227e6eedb', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains access to the in-vehicle network via compromised ECU, telematics unit, Bluetooth, Wi-Fi.', '{"steps":["Attacker gains access to the in-vehicle network via compromised ECU, telematics unit, Bluetooth, Wi-Fi.","VCU-to-BMS communication channel is jammed, flooded, or blocked via DoS attack (e.g., CAN bus saturation).","BMS fails to receive valid energy demand signals from the VCU.","BMS enters an inactive state due to missing control inputs."]}'),
    ('86abd49f-5356-56ff-a8e4-f4a9d81c6e29', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains access to the cloud backend (e.g., via credential theft, API vulnerability, misconfigured cloud storage).', '{"steps":["Attacker gains access to the cloud backend (e.g., via credential theft, API vulnerability, misconfigured cloud storage).","Attacker monitors or intercepts the communication link (e.g., LTE/5G) between cloud and gateway.","Sensitive data such as SoX values, firmware update packages, or Battery Passport entries are extracted."]}'),
    ('26a1bf69-4b7c-557a-b0ac-f59abe525c0f', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker compromises the cloud platform or intercepts cloud–gateway communication (e.g., via MITM attack or malicious access).', '{"steps":["Attacker compromises the cloud platform or intercepts cloud–gateway communication (e.g., via MITM attack or malicious access).","Attacker replaces legitimate firmware or model updates with tampered or malicious versions.","Gateway receives and forwards these tampered files to the BMS.","BMS applies the malicious firmware or models, leading to unsafe battery behavior."]}'),
    ('494c8f8b-f508-59b4-8340-270dece8f797', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker targets the wireless link between the cloud and the gateway (e.g., via jamming, protocol flooding, or spoofed disconnects).', '{"steps":["Attacker targets the wireless link between the cloud and the gateway (e.g., via jamming, protocol flooding, or spoofed disconnects).","Critical updates, models, or configuration files are blocked during transmission.","Gateway fails to deliver data to BMS.","BMS operates without updated models."]}'),
    ('6a8b7488-f43c-5168-bece-e428b1396af7', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains unauthorized access to cloud SoX service (e.g., via API token theft, cloud misconfiguration, or insider threat).', '{"steps":["Attacker gains unauthorized access to cloud SoX service (e.g., via API token theft, cloud misconfiguration, or insider threat).","Attacker extracts SoX-related data (State of Health, State of Charge, operational usage patterns).","Data is sold to competitors or used to infer sensitive vehicle usage and degradation behavior."]}'),
    ('c5328225-d63e-50f6-b992-1390fd48d96a', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker compromises the cloud service responsible for SoX computation (via API injection, access token misuse, or privilege escalation).', '{"steps":["Attacker compromises the cloud service responsible for SoX computation (via API injection, access token misuse, or privilege escalation).","Attacker modifies the input parameters or algorithms used for SoX calculation.","Falsified SoX values are sent to the vehicle, displaying incorrect battery condition.","Misrepresented SoX values influence resale value or deceive users about battery health."]}'),
    ('c5a0b322-cd89-5108-92e9-61ad8ef24a65', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker disrupts communication between the cloud and the vehicle gateway (e.g., via jamming, DNS hijacking, or flooding).', '{"steps":["Attacker disrupts communication between the cloud and the vehicle gateway (e.g., via jamming, DNS hijacking, or flooding).","SoX calculation results from the cloud cannot reach the vehicle.","Battery system reverts to simplified or outdated onboard (BMS) SoX estimation.","Reduced SoX precision leads to suboptimal performance, range estimation errors, or user dissatisfaction."]}'),
    ('e8259a94-a542-563b-8058-e5435b14bb1c', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains unauthorized access to cloud firmware repository (via API credential leak, misconfigured access control, or insider access).', '{"steps":["Attacker gains unauthorized access to cloud firmware repository (via API credential leak, misconfigured access control, or insider access).","Attacker downloads firmware images intended for BMS, CMC, or gateway.","Proprietary code is reverse-engineered to extract algorithms, calibration logic, or hardware interface details."]}'),
    ('1e0fcd2b-06a1-5fde-8bff-e0c28ad16f11', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker accesses cloud logs, update metadata, or API endpoints exposing firmware version and component details (e.g., through insecure APIs).', '{"steps":["Attacker accesses cloud logs, update metadata, or API endpoints exposing firmware version and component details (e.g., through insecure APIs).","Version and component type data are correlated with known vulnerabilities in public CVE databases.","Attacker tailors exploits for specific firmware versions of gateway, BMS, or CMC components."]}'),
    ('195ebea2-3cbe-5d68-a65e-63627e743518', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains write access to firmware repository or update pipeline (e.g., CI/CD compromise or API misuse) and injects malicious firmware images.', '{"steps":["Attacker gains write access to firmware repository or update pipeline (e.g., CI/CD compromise or API misuse).","Attacker injects malicious firmware images (e.g., removes safety checks, alters balancing logic).","Compromised firmware is installed on BMS/CMC during update."]}'),
    ('e1778d10-dddd-53f9-a1e2-48737f277177', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains write access to firmware repository or update pipeline (e.g., CI/CD compromise or API misuse) and corrupts firmware files in the cloud update service.', '{"steps":["Attacker gains write access to firmware repository or update pipeline (e.g., CI/CD compromise or API misuse).","Attacker modifies or corrupts firmware files stored in the cloud update service.","Firmware is distributed to BMS/CMC via OTA updates.","Faulty logic causes misreporting of SoX, voltage, temperature, or balancing states."]}'),
    ('3d17ba3b-505a-526b-af09-34f7ec56180a', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains write access to firmware repository or update pipeline (e.g., CI/CD compromise or API misuse) and redistributes older, vulnerable firmware.', '{"steps":["Attacker gains write access to firmware repository or update pipeline (e.g., CI/CD compromise or API misuse).","Attacker reverts firmware versioning data or update manifests in the cloud service.","Older, vulnerable firmware is redistributed to BMS/CMC instead of the latest version."]}'),
    ('e6d979d8-1365-517a-93f3-688acba0b66a', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker disrupts connectivity to the cloud firmware update service (e.g., DNS poisoning, service flooding).', '{"steps":["Attacker disrupts connectivity to the cloud firmware update service (e.g., DNS poisoning, service flooding).","BMS/CMC fail to receive firmware updates."]}'),
    ('63a8f0f6-51aa-5c96-8812-fe13f4824f13', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker exploits weak authentication, misconfigured cloud storage, or API vulnerabilities.', '{"steps":["Attacker exploits weak authentication, misconfigured cloud storage, or API vulnerabilities.","Attacker accesses the battery passport database on the cloud.","Sensitive data is leaked."]}'),
    ('fcae942e-2f07-5900-a1cc-3d92768b13a6', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains write access to battery passport storage  through spoofing and credential theft.', '{"steps":["Attacker gains write access to battery passport storage  through spoofing and credential theft.","Attacker modifies key fields such as cycle count, temperature exposure, or SoH.","Battery condition is falsely recorded as overstressed."]}'),
    ('d5182155-6732-533b-aa06-9c75e2541310', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker obtains access tokens for the battery passport through spoofing and credential theft.', '{"steps":["Attacker obtains access tokens for the battery passport through spoofing and credential theft.","Attacker deletes battery passport records.","Data necessary for resale verification, compliance audits, or warranty validation becomes unavailable."]}'),
    ('f2493078-dfbe-5275-b16f-5ffba0662679', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker identifies exposed debug interfaces such as UART or JTAG, or gets access to the firmware storage on cloud.', '{"steps":["Attacker identifies exposed debug interfaces such as UART or JTAG, or gets access to the firmware storage on cloud.","Attacker extracts the firmware image from flash memory or intercepts OTA updates if encryption is weak.","Attacker reverse-engineers the firmware to uncover proprietary logic and communication protocols."]}'),
    ('40ebf508-dfa8-5118-a05d-21e9213b5d48', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker performs a MitM attack on the in-vehicle CAN or Ethernet bus.', '{"steps":["Attacker performs a MitM attack on the in-vehicle CAN or Ethernet bus.","Attacker modifies messages or injects unauthorized control data due to weak or missing authentication.","Attacker uploads manipulated firmware with altered access control or embedded SoX model logic."]}'),
    ('445a2af8-5fb0-5556-8c42-dd9a7ed91e43', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker identifies exposed debug interfaces such as UART or JTAG.', '{"steps":["Attacker identifies exposed debug interfaces such as UART or JTAG.","Attacker extracts the firmware image from flash memory or intercepts OTA updates if encryption is weak.","Attacker reverse-engineers the firmware to uncover proprietary logic and communication protocols.","Battery Passport and model data fail to reach the cloud, disrupting traceability and compliance."]}'),
    ('23f082ac-f74b-5434-a127-a152b5ed668a', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker injects malformed or flooding messages on the internal vehicle network to disrupt gateway-BMS communication.', '{"steps":["Attacker injects malformed or flooding messages on the internal vehicle network to disrupt gateway-BMS communication.","Attacker installs corrupted firmware on the gateway that disables data forwarding functions.","Attacker overloads gateway resources using large or repeated model update requests.","SoX or firmware updates are not delivered to the BMS, leading to degraded or outdated operation."]}'),
    ('a896ef39-5e37-553b-89f7-e764c6fc9161', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker intercepts unencrypted or poorly protected communication between the gateway and the cloud wireless interface.', '{"steps":["Attacker intercepts unencrypted or poorly protected communication between the gateway and the cloud wireless interface.","Confidential data such as SoX calculations, or Battery Passport information is captured."]}'),
    ('e6834a11-2f0a-5a17-bb6c-1dbce6c17de5', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker performs a MitM attack between the gateway and cloud (e.g., via rogue base station or network proxy).', '{"steps":["Attacker performs a MitM attack between the gateway and cloud (e.g., via rogue base station or network proxy).","Attacker modifies transmitted data packets (e.g., SoC/SoH) using packet injection or protocol fuzzing.","Gateway does not validate data integrity due to missing or weak MAC/signature mechanisms.","Cloud database stores manipulated battery state, leading to incorrect decisions in maintenance, warranty."]}'),
    ('45447130-8c6e-5f22-878d-2bf805a37235', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker jams or floods the wireless communication channel (e.g., LTE, Wi-Fi) to block data upload.', '{"steps":["Attacker jams or floods the wireless communication channel (e.g., LTE, Wi-Fi) to block data upload.","Attacker manipulates DNS, TLS, or routing configurations to break the gateway’s cloud connection.","Gateway firmware is tampered with to disable cloud communication modules or overload CPU/memory.","Cloud fails to receive updates, interrupting real-time monitoring, firmware updates, and analytics-based decision-making."]}'),
    ('130aa56b-1f15-5fb3-b472-2baa8a728abc', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains access to the firmware update server.', '{"steps":["Attacker gains access to the firmware update server.","Firmware image is extracted from the storage."]}'),
    ('ab14fa00-decd-5491-b6b8-8bdbee3dde48', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker intercepts or manipulates the firmware update process (e.g., by spoofing the update server).', '{"steps":["Attacker intercepts or manipulates the firmware update process (e.g., by spoofing the update server).","A valid but outdated firmware image is injected into the system.","Gateway lacks rollback protection."]}'),
    ('ee5173f9-e7d7-59cb-93e1-9d858fb3eadc', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker blocks communication between the gateway and update server through jamming.', '{"steps":["Attacker blocks communication between the gateway and update server through jamming.","Update request is dropped, delayed, or corrupted during transmission.","Gateway fails to receive the update package."]}'),
    ('190c0ab7-b51b-5abe-913a-f22f26a83fc9', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker blocks the delivery path by jamming.', '{"steps":["Attacker blocks the delivery path by jamming.","Update fails to install, leaving the gateway in a non-functional state or stuck in a boot loop."]}'),
    ('b96215aa-ff5f-5b04-8f05-6bb7821111ea', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker intercepts unencrypted or poorly protected communication between the gateway and the BMS (e.g. CAN, Ethernet).', '{"steps":["Attacker intercepts unencrypted or poorly protected communication between the gateway and the BMS (e.g. CAN, Ethernet).","Confidential data such as SoX calculations, firmware update packages, or Battery Passport information is captured."]}'),
    ('f89980ed-c0e0-5d5e-acc0-ab6633a0a000', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains access to the communication bus between gateway and BMS (e.g., through compromised ECU or physical access).', '{"steps":["Attacker gains access to the communication bus between gateway and BMS (e.g., through compromised ECU or physical access).","SoC-related data is modified in transit (e.g., manipulated current/voltage/time profiles).","BMS uses falsified data for SoC calculation, which may lead to overcharge, deep discharge, or inaccurate balancing decisions."]}'),
    ('3f28c994-f975-5cb3-a507-8eec0b59cec9', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker disrupts the data path between gateway and BMS by sending high-priority CAN messages at a high rate', '{"steps":["Attacker disrupts the data path between gateway and BMS by sending high-priority CAN messages at a high rate","Firmware/configuration updates intended for the BMS are dropped or never reach their destination.","BMS continues to operate on outdated software or parameters."]}'),
    ('b19611cd-ee85-59d5-8998-ef2b9d6e6d2a', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains access to BMS firmware via insecure OTA update or physical interface.', '{"steps":["Attacker gains access to BMS firmware via insecure OTA update or physical interface.","Attacker modifies the overcharge protection logic to increase voltage thresholds or disable triggers.","BMS allows cells to continue charging beyond safe voltage levels."]}'),
    ('ecf68549-6e87-50bd-ac96-8a4b74cee73b', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker modifies BMS configuration during BMS firmware update to raise allowable charge voltage or bypass safety flags.', '{"steps":["Attacker modifies BMS configuration during BMS firmware update to raise allowable charge voltage or bypass safety flags.","Cells experience overcharge conditions."]}'),
    ('250144b0-465f-5759-a635-977d230637a6', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker floods BMS safety modules via wireless interface, preventing execution of overcharge protection.', '{"steps":["Attacker floods BMS safety modules via wireless interface, preventing execution of overcharge protection.","Overvoltage conditions are undetected."]}'),
    ('4e154d5c-8a15-5936-99ae-7ef55e4ba219', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains access to BMS firmware through compromised OTA update.', '{"steps":["Attacker gains access to BMS firmware through compromised OTA update.","Protection thresholds for undervoltage are altered in the firmware.","BMS allows battery cells to discharge below safe voltage."]}'),
    ('8fd42f6f-8da3-546d-9a97-7027062fb1b9', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker exploits wireless communication by jamming.', '{"steps":["Attacker exploits wireless communication by jamming.","Overdischarge protection is rendered non-functional.","Battery continues discharging without safety cutoffs."]}'),
    ('7b33edf5-187a-5e4e-ad9d-9987e7c8706d', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker disrupts BMS''s ability to detect or react to undervoltage through jamming.', '{"steps":["Attacker disrupts BMS''s ability to detect or react to undervoltage through jamming.","Battery is fully discharged beyond recovery thresholds."]}'),
    ('89c62528-8f25-54d8-ab96-059defe06c8d', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains access to BMS firmware via compromised OTA channel or physical debugging interface.', '{"steps":["Attacker gains access to BMS firmware via compromised OTA channel or physical debugging interface.","Modifies firmware logic to disable temperature thresholds.","BMS fails to intervene during overheating of battery cells."]}'),
    ('0134f24b-d8c1-5153-800a-759ed182f839', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker launches a DoS attack on BMS firmware through jamming, disabling the overtemperature protection.', '{"steps":["Attacker launches a DoS attack on BMS firmware through jamming.","Overtemperature protection mechanisms become unresponsive."]}'),
    ('ecda5e93-62d5-501b-b5ab-fd5e8ebaf368', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker gains access to the BMS firmware via insecure wireless update channel or exposed debug interface.', '{"steps":["Attacker gains access to the BMS firmware via insecure wireless update channel or exposed debug interface.","Alters control logic to disable the low-temperature charge threshold and heating is not activated.","BMS allows high C-rates during charging at sub-zero temperatures."]}'),
    ('eff5ea52-6c98-53df-a225-5ae711192021', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker launches a DoS attack on BMS firmware through jamming, bypassing the under-temperature control.', '{"steps":["Attacker launches a DoS attack on BMS firmware through jamming.","Under-temperature control is bypassed.","Charging proceeds during cold ambient conditions."]}'),
    ('f4882c8a-90c8-5f29-b70c-019284e29790', '085d8499-f196-5fda-a83d-c863c9d8d89d', 'Attacker exploits wireless communication between CMC and BMS by jamming.', '{"steps":["Attacker exploits wireless communication between CMC and BMS by jamming.","Temperature sensor data from CMC is blocked or corrupted before reaching BMS.","BMS is unable to assess battery thermal state. Overheating goes undetected due to missing sensor input."]}'),
    ('e399bff0-3266-5a3d-821f-8aef4b26d236', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'Attacker intercepts EMS firmware during transmission or accesses it locally.', '{"steps":["Attacker intercepts EMS firmware during transmission or accesses it locally.","Attacker extracts and reverse-engineers proprietary EMS firmware."]}'),
    ('da7b0829-9b0d-5e25-be75-fa6b18161aa2', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'Attacker gains access to the EMS update channel or firmware storage.', '{"steps":["Attacker gains access to the EMS update channel or firmware storage.","Malicious code is injected into the firmware image or configuration.","The EMS runs the compromised firmware, resulting in altered or unsafe system behavior."]}'),
    ('67440adc-8614-503b-a593-2c0769822c7a', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'Firmware update is interrupted (e.g., via communication jamming or forced shutdown).', '{"steps":["Firmware update is interrupted (e.g., via communication jamming or forced shutdown).","The EMS is left with incomplete or corrupted firmware.","The EMS fails to boot or operate, disabling charging/discharging functionality."]}'),
    ('2dba35f2-1476-53e1-935c-de65bb591e9c', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'Attacker intercepts Modbus TCP traffic between EMS and BMS (e.g., via MITM attack on the local network).', '{"steps":["Attacker intercepts Modbus TCP traffic between EMS and BMS (e.g., via MITM attack on the local network).","Sensitive battery data (e.g., SoC, SoH, energy flow) is extracted in cleartext.","Stolen data is used for sabotage planning or leaked, damaging customer trust."]}'),
    ('718b2cfa-d084-5249-87c3-25ade202d4e3', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'Attacker injects or modifies Modbus TCP packets using a spoofed EMS IP.', '{"steps":["Attacker injects or modifies Modbus TCP packets using a spoofed EMS IP.","BMS receives falsified PV/grid parameters or control commands.","This causes incorrect energy dispatch decisions."]}'),
    ('6c8c8134-4a7b-5ce9-a65e-5f31e648b5c3', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'Attacker floods the Modbus TCP port (usually port 502) or blocks traffic using a firewall.', '{"steps":["Attacker floods the Modbus TCP port (usually port 502) or blocks traffic using a firewall.","EMS and BMS fail to exchange PV/grid information.","The BMS cannot make energy management decisions."]}'),
    ('aaa0bd9d-24f7-5955-a267-d85175ad7b2a', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'Attacker intercepts Modbus TCP traffic from BMS to EMS (e.g., via network sniffing or MITM).', '{"steps":["Attacker intercepts Modbus TCP traffic from BMS to EMS (e.g., via network sniffing or MITM).","Sensitive battery parameters like SoC, SoH, voltage, and current are captured in plaintext.","Data is analyzed or leaked, enabling sabotage planning or violating confidentiality agreements."]}'),
    ('1875ccad-8919-5ae8-9960-147c83cd557a', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'Attacker gains access to the Modbus TCP communication path.', '{"steps":["Attacker gains access to the Modbus TCP communication path.","SoC or SoH values in Modbus frames are modified in transit to report lower or false values.","EMS responds to manipulated data with harmful energy dispatch."]}'),
    ('2d76a5bb-7659-5e51-9b87-9bef23c2af71', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'Attacker floods port 502 (Modbus TCP) or uses ARP spoofing to isolate BMS.', '{"steps":["Attacker floods port 502 (Modbus TCP) or uses ARP spoofing to isolate BMS.","SoX and other control data are no longer received by the EMS.","EMS loses battery control visibility, disrupting charging/discharging."]}'),
    ('26ebb116-2e43-501b-9664-b9c828a01468', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'Attacker intercepts or extracts EMS firmware from an insecure update channel or storage.', '{"steps":["Attacker intercepts or extracts EMS firmware from an insecure update channel or storage.","Proprietary algorithms and configurations are reverse-engineered.","Intellectual property is replicated or exploited by competitors, harming the manufacturer’s business."]}'),
    ('1f2eda4f-1a0f-5d09-901d-6f84a668c2ca', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'Attacker intercepts the firmware update transmission to the EMS over the network.', '{"steps":["Attacker intercepts the firmware update transmission to the EMS over the network.","The firmware image is modified or injected with malicious code.","EMS installs the tampered firmware, resulting in system malfunction."]}'),
    ('deb8321c-71b2-50e3-a46d-078ed293eccd', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'Attacker disrupts the firmware update channel (e.g., blocks network access or crashes the update service).', '{"steps":["Attacker disrupts the firmware update channel (e.g., blocks network access or crashes the update service).","EMS cannot receive or install critical updates.","System remains on outdated firmware, limiting functionality."]}'),
    ('844801fb-ca8d-5a4d-95d0-903251a6f1ba', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'Attacker intercepts cloud-to-cloud communication containing PV and grid data.', '{"steps":["Attacker intercepts cloud-to-cloud communication containing PV and grid data.","Sensitive operational patterns (e.g., load behavior, generation schedules) are extracted.","Data is exploited for competitive advantage or to plan targeted disruption."]}'),
    ('bc68c109-82ae-5a05-bd2b-de3f230aab9b', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'Attacker gains access to the communication channel between clouds.', '{"steps":["Attacker gains access to the communication channel between clouds.","PV and grid data is altered during transmission.","THI receives false information. No critical consequences."]}'),
    ('6625deee-eb08-5811-92ba-9d6e9cb81f01', '9c159075-4c6a-5723-8471-5e5ba4f0740f', 'Attacker blocks or jams communication between cloud services.', '{"steps":["Attacker blocks or jams communication between cloud services.","PV and grid data cannot be received from ETRA.","THI doesn''t receive grid information. No critical consequences."]}'),
    ('30146441-b8d8-5739-b160-8cc12f5c3615', 'bc04d38b-440d-54c6-847d-4bd7ca873b28', 'First-life operator retains unauthorized access to the firmware update interface.', '{"steps":["First-life operator retains unauthorized access to the firmware update interface.","Firmware is modified or configured incorrectly for second-life conditions.","Battery modules degrade faster due to unsuitable operating parameters."]}'),
    ('fdcc5d12-f5cc-590b-8803-4b2561c2aab2', 'bc04d38b-440d-54c6-847d-4bd7ca873b28', 'The battery management system (BMS) enters firmware update mode, preparing to overwrite existing firmware in flash memory.', '{"steps":["The battery management system (BMS) enters firmware update mode, preparing to overwrite existing firmware in flash memory.","New frimware image begins writing to non-volatile memory.","Due to the DoS (power loss, Can bus flooding, communication jamming), the firmware update process is prematurely stoped. This leaves the BMS with a partial or corrupted firmware image","If the BMS does not include a robust bootloader with rollback or dual-bank firmware support it cannot recover from the bad firmware.","On next power cycle or restart, the BMS attempts to boot but cannot execute incomplete/corrupted firmware,","The BMS is rendered non-functional (bricked), leading to total loss of battery control and operation.","Recovery may require hardware reflashing or physical access."]}'),
    ('39d5f65e-4a75-522e-a399-7505315b3360', 'bc04d38b-440d-54c6-847d-4bd7ca873b28', 'Cryptographic keys, certificates, or tokens from the first life are not renewed during the transition.', '{"steps":["Cryptographic keys, certificates, or tokens from the first life are not renewed during the transition.","Communications remain accessible to unauthorized parties with knowledge of old credentials.","Confidential second-life data is leaked, compromising user privacy or competitive advantage."]}'),
    ('a579d341-6dc8-5033-beb0-749960399a75', 'bc04d38b-440d-54c6-847d-4bd7ca873b28', 'Communications remain accessible to unauthorized parties with knowledge of old credentials.', '{"steps":["Communications remain accessible to unauthorized parties with knowledge of old credentials.","Malicious or conflicting data (e.g., SoX or passport entries) is injected.","Battery passport or SoX records become unreliable, leading to potential warranty or resale disputes."]}'),
    ('7e2344a0-fb9d-5b40-859a-2b41c1dc0754', 'bc04d38b-440d-54c6-847d-4bd7ca873b28', 'Cryptographic credentials (keys, certs, tokens) are not renewed or transferred to the second-life operator.', '{"steps":["Cryptographic credentials (keys, certs, tokens) are not renewed or transferred to the second-life operator.","Communication cannot be established with the battery system.","The second-life operator is unable to configure, monitor, or control the system."]}'),
    ('3876c56f-9af6-5033-b6f7-d43cd5e54fae', 'bc04d38b-440d-54c6-847d-4bd7ca873b28', 'Authentication credentials for the battery passport platform are not updated after lifecycle transition.', '{"steps":["Authentication credentials for the battery passport platform are not updated after lifecycle transition.","A former or unauthorized party uses old credentials to gain access.","Battery passport data is accessed, copied, or falsified, compromising data integrity and trust."]}'),
    ('c6590302-80cf-54d7-b0d3-4f5ae5064c80', 'bc04d38b-440d-54c6-847d-4bd7ca873b28', 'IP-protected data (e.g., configuration files, OEM control logic) remains stored on the system during transition to second life.', '{"steps":["IP-protected data (e.g., configuration files, OEM control logic) remains stored on the system during transition to second life.","The second-life operator or a third party accesses the residual data.","Proprietary strategies are extracted and potentially reused or shared, resulting in loss of OEM business advantage."]}'),
    ('cbed3b54-143a-5215-b10e-fbd79c2beb59', 'bc04d38b-440d-54c6-847d-4bd7ca873b28', 'The battery fingerprint is manipulated during the transition from first to second life.', '{"steps":["The battery fingerprint is manipulated during the transition from first to second life.","The BMS performs a validation check using the modified fingerprint.","Fingerprint mismatch results in BMS rejection of the module, preventing system startup."]}'),
    ('1a469c21-03ff-58a6-ae21-1c946abd6d22', 'bc04d38b-440d-54c6-847d-4bd7ca873b28', 'The second-life operator lacks access to the fingerprint storage due to missing or outdated credentials.', '{"steps":["The second-life operator lacks access to the fingerprint storage due to missing or outdated credentials.","The fingerprint cannot be retrieved or validated during initialization.","The system fails to authenticate the battery module, preventing system startup."]}'),
    ('852408fe-47c2-5aad-9ef2-e282000095e9', 'bc04d38b-440d-54c6-847d-4bd7ca873b28', 'Attacker exploits lack of secure boot or firmware authentication in the CMC update mechanism (e.g., via unsecured OTA or diagnostic interface).', '{"steps":["Attacker exploits lack of secure boot or firmware authentication in the CMC update mechanism (e.g., via unsecured OTA or diagnostic interface).","Uploads manipulated firmware to the CMC that disables or alters critical monitoring/control logic.","CMC fails to detect or respond correctly to overvoltage, undervoltage, or overtemperature conditions. BMS receives false data from CMC."]}'),
    ('aeb7026e-4f21-5515-aaab-b0e43a43c5c9', 'bc04d38b-440d-54c6-847d-4bd7ca873b28', 'Attacker blocks the firmware update process (e.g., through wireless jamming, network spoofing, or corrupting the update package).', '{"steps":["Attacker blocks the firmware update process (e.g., through wireless jamming, network spoofing, or corrupting the update package).","CMC fails to install a critical firmware update.","BMS detects CMC as non-functional.","System checks prevent battery system startup."]}'),
    ('a760e6d2-0d37-55b6-9c0d-92c06638a5f2', 'bc04d38b-440d-54c6-847d-4bd7ca873b28', 'Attacker intercepts or accesses the firmware update process, either remotely (via OTA) or locally (via diagnostic interface).', '{"steps":["Attacker intercepts or accesses the firmware update process, either remotely (via OTA) or locally (via diagnostic interface).","Malicious firmware is injected by bypassing authentication or exploiting inadequate signature checks.","BMS installs tampered firmware lacking correct validation."]}'),
    ('ce36cdeb-d6f4-5f74-b8c3-7a0922ad87fb', 'bc04d38b-440d-54c6-847d-4bd7ca873b28', 'Attacker disrupts the OTA channel using a persistent denial-of-service or injection of corrupted firmware metadata.', '{"steps":["Attacker disrupts the OTA channel using a persistent denial-of-service or injection of corrupted firmware metadata.","BMS fails to complete the update, resulting in an invalid or partially written firmware state.","The BMS halts battery management operations, triggering system interlocks."]}')
